import{G as r,a1 as o,b as l,c as u,ae as e,O as n,M as i,f as d,J as s,ao as h}from"./chunks/framework.l_MR1ur9.js";const f=JSON.parse('{"title":"分布式系统中的相关概念","description":"","frontmatter":{"title":"分布式系统中的相关概念","date":"2024/04/17 10:18:02","author":"花木凋零成兰","tags":[],"categories":["后端开发","Dubbo"]},"headers":[],"relativePath":"Backend/Dubbo/1.分布式系统中的相关概念.md","filePath":"Backend/Dubbo/1.分布式系统中的相关概念.md","lastUpdated":1791630580000}'),E={name:"Backend/Dubbo/1.分布式系统中的相关概念.md"};function _(p,a,c,b,A,m){const t=o("Mermaid");return l(),u("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1713349082000"},[a[1]||(a[1]=e('<h1 id="分布式系统中的相关概念" tabindex="-1">分布式系统中的相关概念 <a class="header-anchor" href="#分布式系统中的相关概念" aria-label="Permalink to &quot;分布式系统中的相关概念&quot;">​</a></h1><h2 id="项目架构目标" tabindex="-1">项目架构目标 <a class="header-anchor" href="#项目架构目标" aria-label="Permalink to &quot;项目架构目标&quot;">​</a></h2><ul><li>高性能: 快速的访问体验</li><li>高可用: 网站服务一直可以正常访问</li><li>可伸缩: 通过硬件增加/减少, 提高/降低处理能力</li><li>高可扩展: 系统间耦合低</li><li>安全性: 安全访问和数据加密</li><li>敏捷性: 随需应变, 快速响应</li></ul><h2 id="集群和分布式" tabindex="-1">集群和分布式 <a class="header-anchor" href="#集群和分布式" aria-label="Permalink to &quot;集群和分布式&quot;">​</a></h2><ul><li>集群: 很多&quot;人&quot;一起, 干一样的事情 <ul><li>一个业务模块, 部署在多台服务器上</li></ul></li><li>分布式: 很多&quot;人&quot;一起, 干不一样的事, 这些事组合成一件事 <ul><li>一个大的业务系统,拆分为小的业务模块, 分别部署在不同的机器上</li></ul></li></ul><h2 id="架构演进" tabindex="-1">架构演进 <a class="header-anchor" href="#架构演进" aria-label="Permalink to &quot;架构演进&quot;">​</a></h2>',6)),(l(),n(h,null,{default:i(()=>[s(t,{id:"mermaid-70",graph:"%0A---%0Atitle%3A%20flowchart%0A---%0A%0Aflowchart%20LR%0A%20%20%20%20%E5%8D%95%E4%BD%93%E6%9E%B6%E6%9E%84%20--%3E%20%E5%9E%82%E7%9B%B4%E6%9E%B6%E6%9E%84%20--%3E%20%E5%88%86%E5%B8%83%E5%BC%8F%E6%9E%B6%E6%9E%84%20--%3E%20SOA%E6%9E%B6%E6%9E%84%20--%3E%20%E5%BE%AE%E6%9C%8D%E5%8A%A1%E6%9E%B6%E6%9E%84%0A%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="单体结构" tabindex="-1">单体结构 <a class="header-anchor" href="#单体结构" aria-label="Permalink to &quot;单体结构&quot;">​</a></h3><p>优点:</p><ul><li>简单; 开发部署方便, 小型项目首选</li></ul><p>缺点:</p><ul><li>项目启动慢</li><li>可靠性差</li><li>可伸缩性差</li><li>可扩展性和可维护性差</li><li>性能低</li></ul><h3 id="垂直架构" tabindex="-1">垂直架构 <a class="header-anchor" href="#垂直架构" aria-label="Permalink to &quot;垂直架构&quot;">​</a></h3><p>垂直架构是指 将单体架构中的多个模块拆分为多个独立的项目, 形成多个独立的单体架构</p><p>存在的问题:</p><ul><li>重复功能太多,在多个单体架构中,可能存在重复模块</li></ul><h3 id="分布式架构" tabindex="-1">分布式架构 <a class="header-anchor" href="#分布式架构" aria-label="Permalink to &quot;分布式架构&quot;">​</a></h3><ul><li><p>分布式架构是指在垂直架构的基础上, 将公共业务模块抽取出来, 作为独立的服务, 供其他调用者消费, 以实现服务的共享和重用.</p></li><li><p>RPC: 远程过程调用, 有非常多的协议和技术都实现了RPC的过程;比如: HTTP REST风格, Java RMI规范, WebService SOAP协议, Hession等等</p></li></ul><p>存在的问题:</p><ul><li>服务提供方一旦产生变更, 所有消费方都需要变更</li></ul><h3 id="soa架构" tabindex="-1">SOA架构 <a class="header-anchor" href="#soa架构" aria-label="Permalink to &quot;SOA架构&quot;">​</a></h3><ul><li><p>SOA：（Service-Oriented Architecture，面向服务的架构）是一个组件模型，它将应用程序的不同功能单元（称为服务）进行拆分，并通过这些服务之间定义良好的接口和契约联系起来。</p></li><li><p>ESB：(Enterparise Servce Bus) 企业服务总线，服务中介。主要是提供了一个服务于服务之间的交互。ESB 包含的功能如：负载均衡，流量控制，加密处理，服务的监控，异常处理，监控告急等等。</p></li></ul><h3 id="微服务架构" tabindex="-1">微服务架构 <a class="header-anchor" href="#微服务架构" aria-label="Permalink to &quot;微服务架构&quot;">​</a></h3><ul><li>微服务架构是在 SOA 上做的升华，微服务架构强调的一个重点是“业务需要彻底的组件化和服务化”，原有的单个业务系统会拆分为多个可以独立开发、设计、运行的小应用。这些小应用之间通过服务完成交互和集成。</li><li>微服务架构 = 80%的SOA服务架构思想 + 100%的组件化架构思想 + 80%的领域建模思想</li></ul><p>特点</p><ul><li>服务实现组件化：开发者可以自由选择开发技术。也不需要协调其他团队</li><li>服务之间交互一般使用REST API</li><li>去中心化：每个微服务有自己私有的数据库持久化业务数据</li><li>自动化部署：把应用拆分成为一个一个独立的单个服务，方便自动化部署、测试、运维</li></ul><p><strong>Dubbo 是SOA时代的产物, SpringCloud是微服务时代的产物</strong></p>',20))])}const q=r(E,[["render",_]]);export{f as __pageData,q as default};
